    #[test]
    fn test_specialization_xp_multiplier() {
        let db_file = Path::new("test_questline_spec.db");
        let _ = std::fs::remove_file(db_file);
        let mut app = App::new(db_file).unwrap();

        // Seed user
        let new_user = User {
            id: Uuid::new_v4(),
            username: "Test User".to_string(),
            class: ClassType::CodeWarlock,
            level: 1,
            xp: 0,
            created_at: Utc::now(),
            specialization: None,
        };
        app.db.insert_user(&new_user).unwrap();
        app.user = Some(new_user);
        app.reload_data().unwrap();

        // 1. Initially user is Level 1, no specialization
        let mut user = app.db.get_user().unwrap().unwrap();
        assert_eq!(user.level, 1);
        assert!(user.specialization.is_none());

        // Set user level to 10
        user.level = 10;
        app.db.update_user(&user).unwrap();
        app.reload_data().unwrap();

        // Check it loaded
        let user = app.user.as_ref().unwrap();
        assert_eq!(user.level, 10);

        // 2. Select specialization
        // For Code Warlock, "Bug Hunter" is valid (+10% XP from Task Completion)
        let mut user_mod = app.user.clone().unwrap();
        user_mod.specialization = Some("Bug Hunter".to_string());
        app.db.update_user(&user_mod).unwrap();
        app.reload_data().unwrap();

        // Verify specialization updated
        assert_eq!(
            app.user.as_ref().unwrap().specialization.as_deref(),
            Some("Bug Hunter")
        );

        // 3. Complete a task and check XP gain
        // Base task completion is 25 XP. With +10% it should be round(25 * 1.1) = 28 XP.
        let task_id = Uuid::new_v4();
        let proj = Project {
            id: Uuid::new_v4(),
            name: "Test Project".to_string(),
            description: None,
            archived: false,
            completed: false,
            created_at: Utc::now(),
            updated_at: Utc::now(),
            owner_identity: None,
            owner_username: None,
            is_shared: false,
        };
        app.db.insert_project(&proj).unwrap();
        let t = Task {
            id: task_id,
            project_id: Some(proj.id),
            title: "Quest".to_string(),
            description: None,
            priority: TaskPriority::Medium,
            due_date: None,
            set_date: None,
            completed: false,
            created_at: Utc::now(),
            updated_at: Utc::now(),
            owner_identity: None,
            owner_username: None,
            parent_task_id: None,
            xp_awarded: false,
            recurrence: None,
        };
        app.db.insert_task(&t).unwrap();
        app.active_project_id = Some(proj.id);
        app.selected_task_idx = 0;
        app.workspace_tab_idx = 0;
        app.active_screen = ActiveScreen::Workspace;
        app.reload_data().unwrap();

        // Set key code space to toggle completion
        app.handle_key_event(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::empty()))
            .unwrap();

        // Check user XP. Level 10 has xp = 0.
        // Granting 28 XP should make user.xp = 28.
        let user_after = app.db.get_user().unwrap().unwrap();
        assert_eq!(user_after.xp, 28);

        let _ = std::fs::remove_file(db_file);
    }

    #[test]
    fn unresolved_blocker_prevents_workspace_quest_completion() {
        let db_file = Path::new("test_questline_blocked_completion.db");
        let _ = std::fs::remove_file(db_file);
        let mut app = App::new(db_file).unwrap();
        let project_id = Uuid::new_v4();
        let now = Utc::now();
        let project = Project {
            id: project_id,
            name: "Blocked Campaign".to_string(),
            description: None,
            archived: false,
            completed: false,
            created_at: now,
            updated_at: now,
            owner_identity: None,
            owner_username: None,
            is_shared: false,
        };
        app.db.insert_project(&project).unwrap();

        let make_task = |title: &str| Task {
            id: Uuid::new_v4(),
            project_id: Some(project_id),
            title: title.to_string(),
            description: None,
            priority: TaskPriority::Medium,
            due_date: None,
            set_date: None,
            completed: false,
            created_at: now,
            updated_at: now,
            owner_identity: None,
            owner_username: None,
            parent_task_id: None,
            xp_awarded: false,
            recurrence: None,
        };
        let dependent = make_task("A Dependent Quest");
        let blocker = make_task("B Open the Gate");
        app.db.insert_task(&dependent).unwrap();
        app.db.insert_task(&blocker).unwrap();
        app.db
            .add_task_dependency(
                &dependent.id.to_string(),
                &blocker.id.to_string(),
                &project_id.to_string(),
                "owner",
                "Owner",
            )
            .unwrap();

        app.active_screen = ActiveScreen::Workspace;
        app.active_project_id = Some(project_id);
        app.workspace_tab_idx = 0;
        app.workspace_sidebar_focused = false;
        app.all_tasks = app.db.get_tasks().unwrap();
        let visible = visible_workspace_tasks(
            &app.all_tasks,
            project_id,
            None,
            &app.task_filter,
            &app.task_sort,
            &app.search_query,
            Some(&app.db),
            &app.identity.public_key,
        );
        app.selected_task_idx = visible
            .iter()
            .position(|task| task.id == dependent.id)
            .unwrap();
        app.handle_workspace_key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::empty()))
            .unwrap();

        assert!(!app.db.get_task_by_id(dependent.id).unwrap().completed);
        assert!(app.notifications.iter().any(|notification| {
            notification.kind == NotificationKind::Warning
                && notification.message.contains("B Open the Gate")
        }));

        drop(app);
        let _ = std::fs::remove_file(db_file);
    }

