    #[test]
    fn test_visible_workspace_tasks_keeps_completed_steps_after_parent() {
        let project_id = Uuid::new_v4();
        let parent_id = Uuid::new_v4();
        let now = Utc::now();
        let parent = Task {
            id: parent_id,
            project_id: Some(project_id),
            title: "Parent".to_string(),
            description: None,
            priority: TaskPriority::Medium,
            due_date: None,
            set_date: None,
            completed: false,
            created_at: now,
            updated_at: now,
            owner_identity: None,
            owner_username: None,
            parent_task_id: None,
            xp_awarded: false,
            recurrence: None,
        };
        let open_step = Task {
            id: Uuid::new_v4(),
            project_id: Some(project_id),
            title: "Open Step".to_string(),
            description: None,
            priority: TaskPriority::Medium,
            due_date: None,
            set_date: None,
            completed: false,
            created_at: now + chrono::Duration::seconds(1),
            updated_at: now,
            owner_identity: None,
            owner_username: None,
            parent_task_id: Some(parent_id),
            xp_awarded: false,
            recurrence: None,
        };
        let done_step = Task {
            id: Uuid::new_v4(),
            project_id: Some(project_id),
            title: "Done Step".to_string(),
            description: None,
            priority: TaskPriority::Medium,
            due_date: None,
            set_date: None,
            completed: true,
            created_at: now + chrono::Duration::seconds(2),
            updated_at: now,
            owner_identity: None,
            owner_username: None,
            parent_task_id: Some(parent_id),
            xp_awarded: true,
            recurrence: None,
        };
        let visible = visible_workspace_tasks(
            &[parent.clone(), done_step.clone(), open_step.clone()],
            project_id,
            None,
            "All",
            "CreatedDate",
            "",
            None,
            "",
        );

        assert_eq!(visible.len(), 3);
        assert_eq!(visible[0].id, parent.id);
        assert_eq!(visible[1].id, open_step.id);
        assert_eq!(visible[2].id, done_step.id);
    }

    #[test]
    fn quest_board_navigation_moves_spatially_and_skips_empty_columns() {
        let statuses = [
            QuestStatus::Backlog,
            QuestStatus::Backlog,
            QuestStatus::InProgress,
            QuestStatus::InProgress,
            QuestStatus::Done,
        ];

        assert_eq!(move_quest_board_selection(&statuses, 0, 0, 1), 1);
        assert_eq!(move_quest_board_selection(&statuses, 1, 0, 1), 0);
        assert_eq!(move_quest_board_selection(&statuses, 1, 1, 0), 3);
        assert_eq!(move_quest_board_selection(&statuses, 3, 1, 0), 4);
        assert_eq!(move_quest_board_selection(&statuses, 4, 1, 0), 0);
        assert_eq!(move_quest_board_selection(&statuses, 0, -1, 0), 4);
    }

