    #[test]
    fn test_quick_note_shortcut_and_palette_action_save_a_scroll() {
        let db_file = Path::new("test_questline_quick_note.db");
        let _ = std::fs::remove_file(db_file);
        let mut app = App::new(db_file).unwrap();
        app.config.sync_enabled = false;

        let user = User {
            id: Uuid::new_v4(),
            username: "Quick Scribe".to_string(),
            class: ClassType::CodeWarlock,
            level: 1,
            xp: 0,
            created_at: Utc::now(),
            specialization: None,
        };
        app.db.insert_user(&user).unwrap();
        app.user = Some(user);

        let project = Project {
            id: Uuid::new_v4(),
            name: "Selected Campaign".to_string(),
            description: None,
            archived: false,
            completed: false,
            created_at: Utc::now(),
            updated_at: Utc::now(),
            owner_identity: None,
            owner_username: None,
            is_shared: false,
        };
        app.db.insert_project(&project).unwrap();
        app.reload_data().unwrap();
        app.active_screen = ActiveScreen::Dashboard;

        app.handle_key_event(KeyEvent::new(KeyCode::Char('n'), KeyModifiers::CONTROL))
            .unwrap();
        let editor = app.editor_state.as_ref().expect("quick-note editor");
        assert_eq!(app.active_screen, ActiveScreen::Editor);
        assert!(editor.quick_note);
        assert_eq!(editor.project_id, project.id);

        // Cancelling the dashboard shortcut returns to the dashboard.
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.active_screen, ActiveScreen::Dashboard);

        // The command-palette action opens the same title → campaign → body flow.
        app.execute_command_action("create_note").unwrap();
        for c in "Fast Note".chars() {
            app.handle_key_event(KeyEvent::new(KeyCode::Char(c), KeyModifiers::empty()))
                .unwrap();
        }
        app.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::empty()))
            .unwrap();
        assert!(app.editor_state.as_ref().unwrap().editing_project);
        app.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char('H'), KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char('i'), KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL))
            .unwrap();

        assert_eq!(app.active_screen, ActiveScreen::Editor);
        assert_eq!(app.editor_state.as_ref().unwrap().note_id.is_some(), true);
        assert!(!app.editor_state.as_ref().unwrap().has_unsaved_changes());
        let notes = app.db.get_notes_for_project(project.id).unwrap();
        assert_eq!(notes.len(), 1);
        assert_eq!(notes[0].title, "Fast Note");
        assert_eq!(notes[0].markdown_content, "Hi");

        // A clean editor closes without prompting: Insert → Normal → close.
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.active_screen, ActiveScreen::Dashboard);

        let _ = std::fs::remove_file(db_file);
    }

    #[test]
    fn test_ritual_modal_navigation_and_spaces() {
        let db_file = Path::new("test_questline_ritual_modal.db");
        let _ = std::fs::remove_file(db_file);
        let mut app = App::new(db_file).unwrap();

        // 1. Open NewRitual modal
        app.modal_state = ModalType::NewRitual {
            name: String::new(),
            desc: String::new(),
            frequency_idx: 0,
            reward_xp: "20".to_string(),
            focus_idx: 0,
        };

        // 2. Type characters including space on focus_idx 0 (name)
        app.handle_key_event(KeyEvent::new(KeyCode::Char('H'), KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char('a'), KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::empty()))
            .unwrap();
        app.handle_key_event(KeyEvent::new(KeyCode::Char('b'), KeyModifiers::empty()))
            .unwrap();

        match app.modal_state {
            ModalType::NewRitual {
                ref name,
                focus_idx,
                ..
            } => {
                assert_eq!(name, "Ha b");
                assert_eq!(focus_idx, 0);
            }
            _ => panic!("Expected ModalType::NewRitual"),
        }

        // 3. Cycle using Tab
        app.handle_key_event(KeyEvent::new(KeyCode::Tab, KeyModifiers::empty()))
            .unwrap();
        match app.modal_state {
            ModalType::NewRitual { focus_idx, .. } => {
                assert_eq!(focus_idx, 1);
            }
            _ => panic!("Expected ModalType::NewRitual"),
        }

        // 4. Cycle backward using BackTab (Shift+Tab)
        app.handle_key_event(KeyEvent::new(KeyCode::BackTab, KeyModifiers::empty()))
            .unwrap();
        match app.modal_state {
            ModalType::NewRitual { focus_idx, .. } => {
                assert_eq!(focus_idx, 0);
            }
            _ => panic!("Expected ModalType::NewRitual"),
        }

        let _ = std::fs::remove_file(db_file);
    }

    #[test]
    fn test_global_search_and_palette_shortcuts() {
        let db_file = Path::new("test_questline_global_shortcuts.db");
        let _ = std::fs::remove_file(db_file);
        let mut app = App::new(db_file).unwrap();

        // 1. Press Ctrl+P globally to open CommandPalette modal
        app.modal_state = ModalType::None;
        app.handle_key_event(KeyEvent::new(KeyCode::Char('p'), KeyModifiers::CONTROL))
            .unwrap();
        match app.modal_state {
            ModalType::CommandPalette { .. } => {}
            _ => panic!("Expected ModalType::CommandPalette"),
        }

        // 2. Escape to close
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.modal_state, ModalType::None);

        // 2b. Press : globally to open CommandPalette modal
        app.handle_key_event(KeyEvent::new(KeyCode::Char(':'), KeyModifiers::empty()))
            .unwrap();
        match app.modal_state {
            ModalType::CommandPalette { .. } => {}
            _ => panic!("Expected ModalType::CommandPalette via ':'"),
        }

        // Escape to close
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.modal_state, ModalType::None);

        // 3. Press Ctrl+K to open CommandPalette
        app.handle_key_event(KeyEvent::new(KeyCode::Char('k'), KeyModifiers::CONTROL))
            .unwrap();
        match app.modal_state {
            ModalType::CommandPalette { .. } => {}
            _ => panic!("Expected ModalType::CommandPalette"),
        }

        // 4. Escape to close
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.modal_state, ModalType::None);

        // 5. Press F1 to open CommandPalette
        app.handle_key_event(KeyEvent::new(KeyCode::F(1), KeyModifiers::empty()))
            .unwrap();
        match app.modal_state {
            ModalType::CommandPalette { .. } => {}
            _ => panic!("Expected ModalType::CommandPalette"),
        }

        // 6. Escape to close
        app.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.modal_state, ModalType::None);

        // Test fuzzy matching
        let actions = app.get_available_command_actions("camp");
        assert!(!actions.is_empty());
        assert_eq!(actions[0].name, "Open Campaigns");

        let actions = app.get_available_command_actions("sync");
        assert!(!actions.is_empty());
        assert_eq!(actions[0].name, "Open Sync");

        let actions = app.get_available_command_actions("char");
        assert!(!actions.is_empty());
        assert_eq!(actions[0].name, "Open Character");

        assert_eq!(
            app.get_available_command_actions("my quests")
                .first()
                .map(|action| action.id),
            Some("show_my_quests")
        );
        app.active_screen = ActiveScreen::Workspace;
        app.active_project_id = Some(Uuid::new_v4());
        assert_eq!(
            app.get_available_command_actions("review queue")
                .first()
                .map(|action| action.id),
            Some("show_review_queue")
        );
        app.execute_command_action("show_review_queue").unwrap();
        assert_eq!(app.task_filter, "Review");
        assert_eq!(app.workspace_tab_idx, 0);
        app.active_screen = ActiveScreen::Dashboard;
        app.active_project_id = None;

        // 7. Press ? to open About screen (since we are not in text entry)
        app.handle_key_event(KeyEvent::new(KeyCode::Char('?'), KeyModifiers::empty()))
            .unwrap();
        assert_eq!(app.active_screen, ActiveScreen::About);
        assert_eq!(app.active_tab_idx, 13);

        let _ = std::fs::remove_file(db_file);
    }

